#include <iostream>

int binarySearch(const int list[], int key, int listSize) {
    int low = 0;
    int high = listSize - 1;

    while (high >= low) {
        int mid = low + (high - low) / 2;
        if (key < list[mid]) {
            high = mid - 1;
        } else if (key == list[mid]) {
            return mid;
        } else {
            low = mid + 1;
        }
    }
    return -low - 1;
}

int main() {
    const int data[] = {2, 4, 7, 10, 11, 45, 50, 59, 60, 66, 69, 70, 79};
    int n = sizeof(data) / sizeof(data[0]);

    int testKeys[] = {2, 11, 12, 1, 3};
    for (int key : testKeys) {
        int res = binarySearch(data, key, n);
        if (res >= 0) {
            std::cout << "Key " << key << " found at index " << res << "\n";
        } else {
            int insertPoint = -res - 1;
            std::cout << "Key " << key << " not found. Result: " << res
                      << " (insert at index " << insertPoint << ")\n";
        }
    }
    return 0;
}

#include <iostream>
#include <utility>

void selectionSortAscending(double list[], int listSize) {
    for (int i = 0; i < listSize - 1; ++i) {
        double currentMin = list[i];
        int currentMinIndex = i;

        for (int j = i + 1; j < listSize; ++j) {
            if (currentMin > list[j]) {
                currentMin = list[j];
                currentMinIndex = j;
            }
        }

        if (currentMinIndex != i) {
            std::swap(list[i], list[currentMinIndex]);
        }
    }
}

void selectionSortDescending(double list[], int listSize) {
    for (int i = 0; i < listSize - 1; ++i) {
        double currentMax = list[i];
        int currentMaxIndex = i;

        for (int j = i + 1; j < listSize; ++j) {
            if (currentMax < list[j]) {
                currentMax = list[j];
                currentMaxIndex = j;
            }
        }

        if (currentMaxIndex != i) {
            std::swap(list[i], list[currentMaxIndex]);
        }
    }
}

void printArray(const double list[], int size) {
    for (int i = 0; i < size; ++i) {
        std::cout << list[i] << (i + 1 < size ? " " : "\n");
    }
}

int main() {
    double arr1[] = {1.0, 9.0, 4.5, 6.6, 5.7, -4.5};
    int n1 = sizeof(arr1) / sizeof(arr1[0]);
    selectionSortAscending(arr1, n1);
    printArray(arr1, n1);

    double arr2[] = {3.4, 5.0, 3.0, 3.5, 2.2, 1.9, 2.0};
    int n2 = sizeof(arr2) / sizeof(arr2[0]);
    selectionSortDescending(arr2, n2);
    printArray(arr2, n2);

    return 0;
}

#include <iostream>

int main() {
    // Valid C-string initialized with string literal
    char city1[] = "Dallas"; // size is 7 (6 letters + '\0')

    // Explicit size with null terminator
    char city2[7] = "Dallas";

    std::cout << "city1: " << city1 << "\n";
    std::cout << "Size of city1 in bytes: " << sizeof(city1) << "\n";
    std::cout << "city2: " << city2 << "\n";

    // Inspecting individual characters including null terminator
    for (size_t i = 0; i < sizeof(city1); ++i) {
        if (city1[i] == '\0') {
            std::cout << "Index " << i << ": \\0 (ASCII " << static_cast<int>(city1[i]) << ")\n";
        } else {
            std::cout << "Index " << i << ": " << city1[i] << "\n";
        }
    }
    return 0;
}
